package com.lazygarden.game

/** Independent work plans; milliseconds advance only while their native scene is visible. */
object RestorationSequence {
 data class Step(val key:String,val duration:Long,val speaker:Int=-1,val line:String="",val sound:String="")
 data class Plan(val task:Int,val title:String,val steps:List<Step>){
  val duration get()=steps.sumOf{it.duration}
  fun index(ms:Long):Int {var end=0L;steps.forEachIndexed{i,s->end+=s.duration;if(ms<end)return i};return steps.lastIndex}
  fun fraction(ms:Long):Float {val i=index(ms);return ((ms-steps.take(i).sumOf{it.duration})/steps[i].duration.toFloat()).coerceIn(0f,1f)}
  fun progress(ms:Long,key:String):Float {val i=steps.indexOfFirst{it.key==key};if(i<0)return 0f;return ((ms-steps.take(i).sumOf{it.duration})/steps[i].duration.toFloat()).coerceIn(0f,1f)}
 }
 private fun live(task:Int,title:String,inspect:String,worker:String,family:String,steps:List<Step>)=Plan(task,title,listOf(
  Step("ARRIVAL",3200),Step("INSPECT",3000,0,inspect),*steps.toTypedArray(),
  Step("REVEAL",2800,2,family,"bloom"),Step("CELEBRATE",3200,3,"E përfunduam së bashku!","reward")
 ))
 fun plan(task:Int)=when(task){
  2->Plan(2,"Shtegu i kujtimeve",listOf(Step("ARRIVAL",3500),Step("INSPECT",3500,0,"Gurët janë çarë. Ta hapim shtegun!"),Step("CLEAR",4000,sound="brush"),Step("REMOVE",4000,sound="stone"),Step("LEVEL",4000,sound="shovel"),Step("PLACE",8000,1,"Një nga një, gurët marrin vend.","stone"),Step("CLEAN",3000,sound="brush"),Step("REVEAL",2500,2,"Tani mund të ecim mes luleve!","bloom"),Step("CELEBRATE",3000,3,"Sa shteg i bukur!","reward")))
  3->Plan(3,"Një vend për pushim",listOf(Step("ARRIVAL",3500),Step("INSPECT",3000,0,"Stoli lëkundet. Dërrasat janë kalbur."),Step("REMOVE",4000,sound="hammer"),Step("REPAIR",4500,1,"Po shtrëngoj lidhjet e reja.","hammer"),Step("SAND",4000,sound="brush"),Step("PAINT",5000,2,"Një shtresë bojë do ta mbrojë.","brush"),Step("ASSEMBLE",3500,sound="hammer"),Step("CLEAN",2000,sound="brush"),Step("TRY",3500,3,"E provova! Tani është i sigurt."),Step("CELEBRATE",3000,0,"Një vend për të pushuar së bashku!","reward")))
  4->Plan(4,"Rrënjë të reja",listOf(Step("ARRIVAL",3500),Step("INSPECT",3000,2,"Toka ka nevojë për kujdes."),Step("CLEAR",3500,sound="brush"),Step("WEED",4000,1,"Po heq rrënjët e barërave.","shovel"),Step("SOIL",4000,sound="shovel"),Step("PLANT",6000,2,"Pemët e reja do të rriten këtu.","plant"),Step("WATER",4000,sound="water"),Step("GROW",4000,3,"Shikoni sa gjelbërim!","bloom"),Step("CELEBRATE",3000,0,"Kopshti merr frymë përsëri!","reward")))
  5->Plan(5,"Porta e hapur",listOf(Step("ARRIVAL",3500),Step("INSPECT",3000,0,"Porta ngec. Menteshat duhen ndrequr."),Step("CLEAR",3500,sound="brush"),Step("REPAIR",6000,1,"Po rregulloj menteshat dhe shtyllat.","hammer"),Step("PAINT",5000,sound="brush"),Step("DECORATE",4000,2,"Lulet do t’i mirëpresin miqtë.","plant"),Step("LIGHT",3000,sound="star"),Step("REVEAL",3000,3,"Porta hapet dhe fenerët ndriçojnë!"),Step("CELEBRATE",3000,0,"Mirë se vini në kopshtin tonë!","reward")))
  6->Plan(6,"Shtëpia merr jetë",listOf(Step("ARRIVAL",4000),Step("INSPECT",3500,0,"Tani është radha e shtëpisë."),Step("SCAFFOLD",3500,sound="stone"),Step("CLEAN",4000,sound="brush"),Step("REPAIR",5000,1,"Çarjet po mbyllen një nga një.","hammer"),Step("ROOF",4500,sound="hammer"),Step("PLASTER",4500,sound="shovel"),Step("PAINT",6000,2,"Ngjyrat e ngrohta i japin jetë.","brush"),Step("WINDOWS",4000,sound="hammer"),Step("DECORATE",4000,3,"Edhe vazot e dritareve janë gati!","plant"),Step("LIGHT",3000,sound="star"),Step("REVEAL",4000,0,"E ndërtuam së bashku!","bloom"),Step("CELEBRATE",5000,2,"Kjo pronë është përsëri shtëpi!","reward")))
  7->live(7,"Brendësia e shtëpisë","Brenda ka shumë punë. Ta pastrojmë dhe ta rregullojmë.","Muret po bëhen të forta përsëri.","Tani shtëpia ndihet e ngrohtë.",listOf(Step("CLEAR",3500,sound="brush"),Step("REPAIR",5000,1,"Muret po bëhen të forta përsëri.","hammer"),Step("PLASTER",4500,sound="shovel"),Step("PAINT",5000,sound="brush"),Step("CLEAN",3000,sound="brush")))
  8->live(8,"Dritare me dritë","Dritaret e vjetra nuk mbyllen mirë.","Besi po vendos kornizat dhe xhamat e rinj.","Sa shumë dritë hyri brenda!",listOf(Step("REMOVE",3500,sound="hammer"),Step("WINDOWS",6500,1,"Besi po vendos kornizat dhe xhamat e rinj.","hammer"),Step("REPAIR",3500,sound="hammer"),Step("CLEAN",2800,sound="brush")))
  9->live(9,"Çatia e sigurt","Çatia duhet rregulluar para shiut.","Nermiri po vendos tjegullat me radhë.","Tani jemi të mbrojtur nga shiu.",listOf(Step("SCAFFOLD",3200,sound="stone"),Step("REMOVE",3500,sound="hammer"),Step("ROOF",7000,1,"Nermiri po vendos tjegullat me radhë.","hammer"),Step("REPAIR",3500,sound="hammer"),Step("CLEAN",2500,sound="brush")))
  10->live(10,"Dhoma e fëmijëve","Fëmijët kanë nevojë për një dhomë të sigurt dhe të bukur.","Po montojmë mobiliet që të jenë të forta.","Këtu mund të lexojmë dhe të luajmë!",listOf(Step("CLEAR",3000,sound="brush"),Step("PAINT",5000,sound="brush"),Step("ASSEMBLE",6000,1,"Po montojmë mobiliet që të jenë të forta.","hammer"),Step("DECORATE",4500,sound="plant")))
  11->live(11,"Kuzhina e familjes","Kuzhina duhet pastruar dhe riparuar.","Po rregullojmë dollapët dhe sipërfaqet.","Tani mund të gatuajmë së bashku.",listOf(Step("CLEAR",3200,sound="brush"),Step("REPAIR",5200,1,"Po rregullojmë dollapët dhe sipërfaqet.","hammer"),Step("ASSEMBLE",4500,sound="hammer"),Step("PAINT",4200,sound="brush"),Step("CLEAN",2800,sound="brush")))
  12->live(12,"Instalimet e kuzhinës","Uji dhe rryma duhet të jenë gati para përdorimit.","Po kontrollojmë lidhjet një nga një.","Tani kuzhina është gati për familjen.",listOf(Step("REPAIR",5200,1,"Rexha po kontrollon tubat dhe lidhjet.","water"),Step("LIGHT",5200,1,"Mevludini po kontrollon instalimin elektrik.","star"),Step("ASSEMBLE",3800,sound="hammer"),Step("TRY",3000,3,"Punon! Gjithçka është në rregull.")))
  13->live(13,"Salloni i përbashkët","Salloni duhet të bëhet vendi ku mblidhemi të gjithë.","Po riparojmë dhe montojmë mobiliet.","Këtu do të kalojmë shumë mbrëmje bashkë.",listOf(Step("CLEAR",3000,sound="brush"),Step("REPAIR",4500,sound="hammer"),Step("PAINT",4500,sound="brush"),Step("ASSEMBLE",5200,1,"Po riparojmë dhe montojmë mobiliet.","hammer"),Step("DECORATE",3500,sound="plant")))
  14->live(14,"Ballkoni i hapur","Ballkoni ka nevojë për siguri dhe pak gjelbërim.","Po forcojmë pjesët e dobëta.","Nga këtu kopshti duket bukur.",listOf(Step("CLEAR",2800,sound="brush"),Step("REPAIR",5200,1,"Po forcojmë pjesët e dobëta.","hammer"),Step("PAINT",4200,sound="brush"),Step("DECORATE",4200,2,"Le t’i vendosim lulet këtu.","plant")))
  15->live(15,"Punishtja","Na duhet një vend ku mjetet të jenë në rregull.","Po montojmë tavolinën dhe raftet e punës.","Tani çdo mjet e ka vendin e vet.",listOf(Step("CLEAR",3000,sound="brush"),Step("REPAIR",4200,sound="hammer"),Step("ASSEMBLE",6200,1,"Po montojmë tavolinën dhe raftet e punës.","hammer"),Step("LIGHT",3500,sound="star"),Step("CLEAN",2500,sound="brush")))
  16->live(16,"Këndi i biçikletave","Biçikletat duhen mbajtur të sigurta dhe të rregulluara.","Po ndërtojmë mbajtëset prej druri.","Tani biçikletat janë gati për xhiro!",listOf(Step("CLEAR",2800,sound="brush"),Step("ASSEMBLE",6000,1,"Po ndërtojmë mbajtëset prej druri.","hammer"),Step("PAINT",3800,sound="brush"),Step("TRY",3200,3,"E vendosa biçikletën. Qëndron fort!")))
  17->live(17,"Dritat e oborrit","Oborri duhet të jetë i ndriçuar edhe në mbrëmje.","Mevludini po lidh dritat me kujdes.","Dritat e bëjnë kopshtin magjik.",listOf(Step("CLEAR",2500,sound="brush"),Step("LIGHT",7200,1,"Mevludini po lidh dritat me kujdes.","star"),Step("REPAIR",3200,sound="hammer"),Step("TRY",3000,3,"U ndezën të gjitha!")))
  18->live(18,"Zona e lojës","Fëmijët duan një vend ku të luajnë të sigurt.","Po montojmë lojërat dhe po kontrollojmë çdo vidë.","Hajde të luajmë!",listOf(Step("LEVEL",3500,sound="shovel"),Step("ASSEMBLE",6500,1,"Po montojmë lojërat dhe po kontrollojmë çdo vidë.","hammer"),Step("PAINT",4200,sound="brush"),Step("TRY",3500,3,"Është e fortë dhe gati për lojë!")))
  19->live(19,"Kopshti për festë","Ka mbetur vetëm prekja e fundit para festës.","Po rregullojmë çdo detaj të fundit.","Prona është gati. Ta festojmë së bashku!",listOf(Step("CLEAN",3500,sound="brush"),Step("DECORATE",5200,2,"Lulet dhe dekorimet po e mbushin oborrin me ngjyra.","plant"),Step("LIGHT",4200,1,"Dritat e festës janë gati.","star"),Step("TRY",3000,3,"Gjithçka është në vend!")))
  else->error("No work plan for task $task")
 }
}
